CREATE OR REPLACE FUNCTION public.verification_open_pipeline(_uid uuid,_company uuid,_pipeline uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN PERFORM 1 FROM public.deal_pipelines WHERE id=_pipeline FOR SHARE; IF NOT public.verification_pipeline_valid(_uid,_company,_pipeline) THEN RAISE EXCEPTION 'An approved, valid NDA is required'; END IF; IF public.verification_can_read(_uid,_company) THEN RETURN jsonb_build_object('reopened',true); END IF; IF NOT EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=_uid AND term_start IS NOT NULL) THEN RAISE EXCEPTION 'Choose an active plan'; END IF; result:=public.verification_open(_uid,_company); RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.verification_open_pipeline(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.verification_open_pipeline(uuid,uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.verification_check_identity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.verification_id IS DISTINCT FROM OLD.verification_id OR NEW.key IS DISTINCT FROM OLD.key THEN RAISE EXCEPTION 'A recorded check cannot be moved to another report or check'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.verification_check_identity_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER verification_check_identity_guard BEFORE UPDATE OF verification_id,key ON public.company_verification_checks FOR EACH ROW EXECUTE FUNCTION public.verification_check_identity_guard();